mapper.sql:
FROM department

    AND (name LIKE CONCAT('%', #{q}, '%') OR code LIKE CONCAT('%', #{q}, '%'))
    AND status = #{status}

FROM doctor d JOIN department dp ON dp.id = d.department_id

    AND d.name LIKE CONCAT('%', #{q}, '%')
    AND d.department_id = #{departmentId}
    AND d.status = #{status}

WHERE 
AND dp.id = #{filters.departmentId}
AND d.id = #{filters.doctorId}
AND sc.schedule_date = #{filters.date}
AND sc.schedule_date >= #{filters.from}
AND sc.schedule_date <= #{filters.to}
AND sc.status = #{filters.status}

mapper.select:
SELECT d.id, d.department_id, dp.name AS department_name, d.name, d.title,
       d.specialty, d.introduction, d.status, COALESCE(d.code,CONCAT('D-',d.id)) AS import_code

ORDER BY dp.name, d.name, d.id LIMIT #{limit} OFFSET #{offset}
